#include <iostream>

int main() {
    int threshold = 0;
    if (!(std::cin >> threshold)) {
        return 0;
    }

    int list[] = {3, 8, 12, 5};
    int count = 0;

    for (int i = 0; i < 4; ++i) {
        if (list[i] >= threshold) {
            count++;
        }
    }

    int category = (count > 2) ? 1 : 0;
    switch (category) {
        case 1:
            std::cout << "Count: " << count << " (High)" << std::endl;
            break;
        case 0:
        default:
            std::cout << "Count: " << count << " (Low)" << std::endl;
            break;
    }

    int matrix[2][2] = {{1, 2}, {3, 4}};
    int diagonalSum = 0;
    int r = 0;
    while (r < 2) {
        diagonalSum += matrix[r][r];
        r++;
    }
    std::cout << "Diagonal Sum: " << diagonalSum << std::endl;

    return 0;
}

#include <iostream>
#include <cctype>
#include <cstring>
#include <string>

int main() {
    char inputChar = 'a';
    if (!(std::cin >> inputChar)) {
        return 0;
    }

    char upperChar = static_cast<char>(std::toupper(static_cast<unsigned char>(inputChar)));
    bool isLetter = std::isalpha(static_cast<unsigned char>(inputChar));

    // Dynamic memory allocation and deallocation
    int* dynamicArr = new int[3];
    dynamicArr[0] = 10;
    dynamicArr[1] = 20;
    dynamicArr[2] = 30;

    int sum = dynamicArr[0] + dynamicArr[1] + dynamicArr[2];
    delete[] dynamicArr;

    // C-string inspection
    const char legacyStr[] = "CppRef";
    std::size_t cLen = std::strlen(legacyStr);

    // Modern std::string manipulation
    std::string s = "Hello";
    s.append("World");
    std::string sub = s.substr(0, 5);

    std::cout << "Input Char: " << inputChar << std::endl;
    std::cout << "Is Alpha: " << (isLetter ? "true" : "false") << std::endl;
    std::cout << "Upper Char: " << upperChar << std::endl;
    std::cout << "Heap Sum: " << sum << std::endl;
    std::cout << "C-String Len: " << cLen << std::endl;
    std::cout << "Sub: " << sub << std::endl;
    std::cout << "Full: " << s << std::endl;

    return 0;
}
